#!/bin/sh
# -*- coding: utf-8 -*-
# Version = 1.0
# TAM - Laurent Chappe 20201005


import tanium
import tanium_base
import urllib
import os
import sys
import tempfile
import re

#Create list where we will store the filename found
files = []


suffix = "_emocheck.txt"

#Slice the file found in 3 part (r)oot, (d)irectory and (f)ilename
for r, d, f in os.walk(tempfile.gettempdir()):
    for file in f:
        if file.endswith(suffix): 
            files.append(os.path.join(r, file)) #rebuild full file name in list created earlier




#Making sensor return a nice message based on OS if nothing found             
if not files:
  if sys.platform.startswith('win32'):
    tanium.results.add("No Emocheck scan file found - Windows") 
  elif sys.platform.startswith('linux'):
    tanium.results.add("No Emocheck scan file found - Linux")
  elif sys.platform.startswith('darwin'):
    tanium.results.add("No Emocheck scan file found - MacOS")
else:
  for f in files:
      print(f)
      with open(f,"r") as fs:
        line_source = fs.readline()
        for line_source in fs:
            if line_source.startswith("Scan time: "):
                scan_date = line_source.strip("Scan time: ")
                scan_day = scan_date.partition(" ")[0]
                scan_time= scan_date.partition(" ")[2]
                scan_time= scan_time.rstrip()

            if line_source.startswith("Emotet was not detected."):
                scan_result = "False"

                tanium.results.add(scan_day+"|"+scan_time+"|"+scan_result+"|"+"|")

            if line_source.startswith("Detected Emotet process."):
                    scan_result = "True"

            if line_source.startswith("     Process Name  : "):
                scan_process = line_source.partition("Process Name  : ")[2]
                scan_process = scan_process.rstrip()
            if line_source.startswith("     Image Path    : "):
                scan_path = line_source.partition("Image Path    : ")[2]
                scan_path = scan_path.rstrip()


                tanium.results.add(scan_day+"|"+scan_time+"|"+scan_result+"|"+scan_process+"|"+scan_path)

